// 1. Tomamos todos los registros que llegaron desde Notion
// y dejamos solamente los que están activos.
const knowledge = $input
  .all()
  .map(item => item.json)
  .filter(item => item.property_activo === true);


// 2. Recuperamos la consulta original desde Airtable Trigger.
const consulta = $('Airtable Trigger').first().json.fields;


// 3. Recuperamos los datos del lead desde el nodo que ya validamos.
const lead = $('Obtener datos del lead').first().json.fields;


// 4. Construimos los tags que representan esta consulta.
const tagsBusqueda = [
  consulta['Operación'],
  consulta['Zona'],
  consulta['Tipo de propiedad'],

  consulta['Presupuesto máximo'] != null ? 'presupuesto' : null,
  consulta['Ambientes'] != null ? 'ambientes' : null,
  consulta['Requisitos'] ? 'requisitos' : null,

  // Estos conocimientos son relevantes para cualquier respuesta.
  'calificación',
  'respuesta',
]
  .filter(Boolean)
  .map(tag => String(tag).trim().toLowerCase());


// 5. Comparamos los tags de cada registro de Notion
// contra los tags de la consulta.
const resultados = knowledge
  .map(registro => {
    const tagsRegistro = (registro.property_tags || [])
      .map(tag => String(tag).trim().toLowerCase());

    const coincidencias = tagsRegistro.filter(tag =>
      tagsBusqueda.includes(tag)
    );

    return {
      ...registro,
      score: coincidencias.length,
      coincidencias,
    };
  })

  // Solo dejamos registros que tengan al menos una coincidencia.
  .filter(registro => registro.score > 0)

  // Los más relevantes quedan primero.
  .sort((a, b) => b.score - a.score);


// 6. Armamos el texto que después enviaremos a Cohere como contexto.
const contextoRag = resultados
  .map(registro =>
    `### ${registro.property_tema}\n${registro.property_contenido}`
  )
  .join('\n\n');


// 7. Devolvemos UN solo item estructurado.
return [
  {
    json: {
      id_consulta: consulta['ID Consulta'],

      lead: {
        nombre: lead['Nombre'] || '',
        email: lead['Email'] || '',
      },

      consulta: {
        operacion: consulta['Operación'] || '',
        tipo_propiedad: consulta['Tipo de propiedad'] || '',
        ambientes: consulta['Ambientes'] ?? null,
        zona: consulta['Zona'] || '',
        presupuesto_maximo: consulta['Presupuesto máximo'] ?? null,
        moneda: consulta['Moneda'] || '',
        requisitos: consulta['Requisitos'] || '',
        mensaje_original: consulta['Mensaje original'] || '',
      },

      tags_busqueda: tagsBusqueda,

    fuentes_rag: resultados.map(registro => ({
    tema: registro.property_tema,
    tags_coincidentes: registro.coincidencias,
    relevancia_rag: registro.score,
})),

      contexto_rag: contextoRag,
    },
  },
];

